<script setup lang="ts">
import {TresCanvas} from '@tresjs/core';import SceneObjects from './SceneObjects.vue';const active=ref(false);const root=ref<HTMLElement>();const enabled=ref(false);let observer:IntersectionObserver;onMounted(()=>{const nav=navigator as any;if(matchMedia('(prefers-reduced-motion: reduce)').matches||nav.connection?.saveData||(nav.deviceMemory&&nav.deviceMemory<4))return;try{const canvas=document.createElement('canvas');if(!canvas.getContext('webgl2'))return;enabled.value=true;observer=new IntersectionObserver(e=>active.value=!!e[0]?.isIntersecting);if(root.value)observer.observe(root.value)}catch{enabled.value=false}});onUnmounted(()=>observer?.disconnect())

</script><template><div ref="root" class="hero-scene"><TresCanvas v-if="enabled&&active" alpha :dpr="[1,2]"><TresPerspectiveCamera :position="[0,0,6]"/><TresAmbientLight :intensity="2"/><TresDirectionalLight :position="[3,4,3]" :intensity="3"/><SceneObjects/></TresCanvas></div></template>
